insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"funny-101","prompt":"Power rarely wears a cape. Where do people feel it in everyday life?","theme":"Power, Rules & Institutions","answers":["Schedules","Rules","Prices","Expectations"],"sort_order":101,"version":"funny"},{"id":"funny-102","prompt":"A rule wants people to respect it. What does it need besides ''because I said so''?","theme":"Power, Rules & Institutions","answers":["Its purpose is clear","It is applied fairly","People have a voice","It can be challenged"],"sort_order":102,"version":"funny"},{"id":"funny-103","prompt":"Name a quiet form of control that doesn’t need a security guard.","theme":"Power, Rules & Institutions","answers":["Ranking","Tracking","Labeling","Rewarding conformity"],"sort_order":103,"version":"funny"},{"id":"funny-104","prompt":"An institution wants your trust back. What should it bring to the apology meeting?","theme":"Power, Rules & Institutions","answers":["Transparency","Accountability","Participation","Consistency"],"sort_order":104,"version":"funny"},{"id":"funny-105","prompt":"Why do people follow rules while mentally rolling their eyes?","theme":"Power, Rules & Institutions","answers":["Fear of consequences","Need for access","Habit","Social pressure"],"sort_order":105,"version":"funny"},{"id":"funny-106","prompt":"An unfair system has been exposed. What’s usually the first move?","theme":"Power, Rules & Institutions","answers":["Naming the problem","Quietly refusing","Finding allies","Imagining an alternative"],"sort_order":106,"version":"funny"},{"id":"funny-107","prompt":"What kind of power works best when nobody notices it’s there?","theme":"Power, Rules & Institutions","answers":["Normalized routines","Expert language","Market incentives","Social expectations"],"sort_order":107,"version":"funny"},{"id":"funny-108","prompt":"How can inequality put on a nice outfit and pretend to be normal?","theme":"Power, Rules & Institutions","answers":["Call it personal failure","Call it natural difference","Call it free choice","Call it efficiency"],"sort_order":108,"version":"funny"},{"id":"funny-109","prompt":"What makes a person think, ''Apparently I’m just account number 472 now''?","theme":"Power, Rules & Institutions","answers":["Metrics dominate","Context is ignored","Time is too limited","Decisions are automated"],"sort_order":109,"version":"funny"},{"id":"funny-110","prompt":"If one group has too much power, what’s the strongest balancing force?","theme":"Power, Rules & Institutions","answers":["Collective action","Public oversight","Local control","Transparency"],"sort_order":110,"version":"funny"},{"id":"funny-111","prompt":"Punishment changes behavior, but what’s usually doing the heavy lifting?","theme":"Power, Rules & Institutions","answers":["Through fear","Through exclusion","Through shame","Through lost opportunities"],"sort_order":111,"version":"funny"},{"id":"funny-112","prompt":"What gets people to obey without anyone technically forcing them?","theme":"Power, Rules & Institutions","answers":["Rewards","Convenience","Uncertainty","Peer pressure"],"sort_order":112,"version":"funny"},{"id":"funny-113","prompt":"When does a rule become the villain of its own origin story?","theme":"Power, Rules & Institutions","answers":["Exceptions become impossible","Context gets ignored","Costs fall unevenly","Dissent gets punished"],"sort_order":113,"version":"funny"},{"id":"funny-114","prompt":"What’s a sign the rulebook has moved inside someone’s head?","theme":"Power, Rules & Institutions","answers":["They constantly self-monitor","They constantly self-blame","They compete constantly","They anticipate judgment"],"sort_order":114,"version":"funny"},{"id":"funny-115","prompt":"What keeps a social hierarchy standing even when nobody admits they built it?","theme":"Power, Rules & Institutions","answers":["Money","Status","Tradition","Access"],"sort_order":115,"version":"funny"},{"id":"funny-116","prompt":"Freedom removes barriers—but what does it still need to be real?","theme":"Power, Rules & Institutions","answers":["Resources","Time","Support","Security"],"sort_order":116,"version":"funny"},{"id":"funny-117","prompt":"What makes bureaucracy feel like a maze designed by people who hate people?","theme":"Power, Rules & Institutions","answers":["There is no discretion","There is no explanation","There is no human contact","There is no appeal"],"sort_order":117,"version":"funny"},{"id":"funny-118","prompt":"If everyone knows they’re being watched, what changes first?","theme":"Power, Rules & Institutions","answers":["More caution","More conformity","More anxiety","More self-censorship"],"sort_order":118,"version":"funny"},{"id":"funny-119","prompt":"Shared power enters the meeting. What does it actually look like?","theme":"Power, Rules & Institutions","answers":["Co-decision","Rotating leadership","Open information","Mutual accountability"],"sort_order":119,"version":"funny"},{"id":"funny-120","prompt":"What usually makes people go from complaining privately to challenging authority publicly?","theme":"Power, Rules & Institutions","answers":["When harm becomes visible","When alternatives exist","When allies gather","When legitimacy weakens"],"sort_order":120,"version":"funny"},{"id":"funny-121","prompt":"People live near each other all the time. What actually turns that into a community?","theme":"Community, Solidarity & Commons","answers":["Shared work","Shared meals","Mutual aid","Shared decisions"],"sort_order":121,"version":"funny"},{"id":"funny-122","prompt":"When does ''we’re all in this together'' stop sounding cheesy and start being true?","theme":"Community, Solidarity & Commons","answers":["People show up","People share risk","People share resources","People listen across differences"],"sort_order":122,"version":"funny"},{"id":"funny-123","prompt":"A shared public resource is doing fine. What’s most likely to wreck it?","theme":"Community, Solidarity & Commons","answers":["Privatization","Neglect","Competition","Short-term thinking"],"sort_order":123,"version":"funny"},{"id":"funny-124","prompt":"What makes strangers suddenly much better at cooperating?","theme":"Community, Solidarity & Commons","answers":["Trust","Fair rules","Visible needs","Shared benefits"],"sort_order":124,"version":"funny"},{"id":"funny-125","prompt":"A community garden has survived for years. What probably kept it alive?","theme":"Community, Solidarity & Commons","answers":["Clear responsibility","Local knowledge","Mutual accountability","Regular daily use"],"sort_order":125,"version":"funny"},{"id":"funny-126","prompt":"What disconnects neighbors faster than a bad Wi-Fi signal?","theme":"Community, Solidarity & Commons","answers":["Everyone being overworked","People moving constantly","Public spaces disappearing","Competition increasing"],"sort_order":126,"version":"funny"},{"id":"funny-127","prompt":"What keeps collective action going after the exciting first meeting?","theme":"Community, Solidarity & Commons","answers":["Friendship","Achievable goals","Shared leadership","Celebration"],"sort_order":127,"version":"funny"},{"id":"funny-128","prompt":"What makes someone say, ''These are my people''?","theme":"Community, Solidarity & Commons","answers":["Repetition","Contribution","Recognition","Shared memory"],"sort_order":128,"version":"funny"},{"id":"funny-129","prompt":"A movement has goals, posters, and a group chat. What else does it desperately need?","theme":"Community, Solidarity & Commons","answers":["Relationships","Joy","Safety","Learning"],"sort_order":129,"version":"funny"},{"id":"funny-130","prompt":"When can an argument make a group stronger instead of splitting the group chat?","theme":"Community, Solidarity & Commons","answers":["It stays respectful","It stays specific","It stays transparent","It stays connected to a shared purpose"],"sort_order":130,"version":"funny"},{"id":"funny-131","prompt":"What makes mutual aid feel different from ''Here, take this and goodbye''?","theme":"Community, Solidarity & Commons","answers":["Reciprocity","Equality","Relationship","Shared struggle"],"sort_order":131,"version":"funny"},{"id":"funny-132","prompt":"What proves a group has learned not to run entirely on burnout?","theme":"Community, Solidarity & Commons","answers":["Tasks are shared","Rest is accepted","Wins are noticed","People are supported"],"sort_order":132,"version":"funny"},{"id":"funny-133","prompt":"How does a community get smarter without buying a textbook?","theme":"Community, Solidarity & Commons","answers":["Storytelling","Practice","Mentoring","Debate"],"sort_order":133,"version":"funny"},{"id":"funny-134","prompt":"What problem gets easier when people stop trying to solve it alone?","theme":"Community, Solidarity & Commons","answers":["Isolation","Time pressure","Resource gaps","Lack of access"],"sort_order":134,"version":"funny"},{"id":"funny-135","prompt":"What makes a public place feel like it belongs to everyone?","theme":"Community, Solidarity & Commons","answers":["People feel welcome","People feel safe","There is shared activity","People help care for it"],"sort_order":135,"version":"funny"},{"id":"funny-136","prompt":"You turn something into a commons. What changes first?","theme":"Community, Solidarity & Commons","answers":["Make it shared","Make it cared for","Govern it collectively","Keep it widely accessible"],"sort_order":136,"version":"funny"},{"id":"funny-137","prompt":"Why do people suddenly become fierce defenders of a shared resource?","theme":"Community, Solidarity & Commons","answers":["They need it daily","It creates belonging","It represents fairness","Future generations need it"],"sort_order":137,"version":"funny"},{"id":"funny-138","prompt":"What makes cooperation collapse faster than someone saying ''I thought YOU were doing it''?","theme":"Community, Solidarity & Commons","answers":["Low trust","Unequal effort","Closed decisions","Uneven rewards"],"sort_order":138,"version":"funny"},{"id":"funny-139","prompt":"What makes a group hard to break when trouble shows up?","theme":"Community, Solidarity & Commons","answers":["Skills are distributed","Information is shared","Leadership is shared","Relationships are strong"],"sort_order":139,"version":"funny"},{"id":"funny-140","prompt":"Name something people can do together that makes collective life feel less like a committee meeting.","theme":"Community, Solidarity & Commons","answers":["Cooking together","Singing together","Building something together","Celebrating together"],"sort_order":140,"version":"funny"},{"id":"funny-141","prompt":"Your body sends a reminder: ''Plot twist, you are part of nature.'' What proves it?","theme":"Nature, Ecology & Interdependence","answers":["Sleep cycles","Sensitivity to weather","Need for fresh air","Need for movement"],"sort_order":141,"version":"funny"},{"id":"funny-142","prompt":"Environmental harm stops being abstract when it reaches what part of daily life?","theme":"Nature, Ecology & Interdependence","answers":["Air","Water","Food","Noise"],"sort_order":142,"version":"funny"},{"id":"funny-143","prompt":"What does modern life make surprisingly easy to forget exists?","theme":"Nature, Ecology & Interdependence","answers":["Seasons","Land","Community","Bodily rhythms"],"sort_order":143,"version":"funny"},{"id":"funny-144","prompt":"Why does sitting under a tree sometimes feel like better customer service than modern life?","theme":"Nature, Ecology & Interdependence","answers":["More quiet","Different sensory input","More movement","Distance from screens"],"sort_order":144,"version":"funny"},{"id":"funny-145","prompt":"If the body isn’t a machine, what metaphor fits better?","theme":"Nature, Ecology & Interdependence","answers":["An organism","An ecosystem","A relationship","A living history"],"sort_order":145,"version":"funny"},{"id":"funny-146","prompt":"What makes an environment quietly tell your body, ''You’re safe here''?","theme":"Nature, Ecology & Interdependence","answers":["Clean air","Green space","Safe water","Quiet places"],"sort_order":146,"version":"funny"},{"id":"funny-147","prompt":"Technology is powerful, but which human need keeps winning every rematch?","theme":"Nature, Ecology & Interdependence","answers":["Need for sleep","Need for connection","Need for rest","Need for a healthy environment"],"sort_order":147,"version":"funny"},{"id":"funny-148","prompt":"What makes a place stop feeling like an address and start feeling like home?","theme":"Nature, Ecology & Interdependence","answers":["Walking","Gardening","Local food","Knowing neighbors"],"sort_order":148,"version":"funny"},{"id":"funny-149","prompt":"Where does environmental inequality show up in the most annoyingly obvious way?","theme":"Nature, Ecology & Interdependence","answers":["Pollution exposure","Extreme heat","Access to green space","Water quality"],"sort_order":149,"version":"funny"},{"id":"funny-150","prompt":"Progress builds things. What should it be forbidden from destroying?","theme":"Nature, Ecology & Interdependence","answers":["Livable ecosystems","Human time","Biodiversity","Community"],"sort_order":150,"version":"funny"}]'::jsonb) r;